// textos con partes que cambian (números, fechas, versión)
const TEC = { 'Rep parcial: recorrido corto': 'Partial rep: short range', 'Faltó profundidad': 'Not deep enough', 'La cadera subió antes que los hombros': 'Hips rose before shoulders',
  'Balanceaste el torso': 'You swung your torso', 'Brazo izquierdo recorrió menos': 'Left arm moved less', 'Brazo derecho recorrió menos': 'Right arm moved less' };
const MESES = { enero: 'January', febrero: 'February', marzo: 'March', abril: 'April', mayo: 'May', junio: 'June', julio: 'July', agosto: 'August', septiembre: 'September', octubre: 'October', noviembre: 'November', diciembre: 'December' };
export const PATRONES = [
  [/^Versión (\S+)$/, 'Version $1'],
  [/^(\d+) días? entrenados?$/, (m, n) => `${n} day${n === '1' ? '' : 's'} trained`],
  [/^(\d+) semanas?$/, (m, n) => `${n} week${n === '1' ? '' : 's'}`],
  [/^· (\d+) entrenamientos? en los últimos 30 días$/, (m, n) => `· ${n} workout${n === '1' ? '' : 's'} in the last 30 days`],
  [/^(\d+) este mes$/, '$1 this month'],
  [/^(Enero|Febrero|Marzo|Abril|Mayo|Junio|Julio|Agosto|Septiembre|Octubre|Noviembre|Diciembre) de (\d{4})$/, (m, mes, a) => `${MESES[mes.toLowerCase()]} ${a}`],
  [/^📐 Cómo grabar: (.+)$/, '📐 How to record: $1'],
  [/^(.+), (De lado|De frente|De atrás|Diagonal|A 45°)$/, (m, a, v) => `${a}, ${EN[v] || v}`],
  [/^\(discos (\S+) \+ máquina (\S+)\)\. Tu peso corporal no se suma\.$/, '(plates $1 + machine $2). Your body weight is not added.'],
  [/^¿Qué es (.+)\?$/, 'What is $1?'],
  [/^Fuerza: (.+)$/, 'Force: $1'], [/^Velocidad: (.+)$/, 'Velocity: $1'], [/^Potencia: (.+)$/, 'Power: $1'], [/^Fuerza aplicada \((.+)\)$/, 'Applied force ($1)'],
  [/^No se pudo cargar (.+)$/, 'Could not load $1'], [/^Error (\d+) del servidor\.$/, 'Server error $1.'],
  [/^Cadencia baja \(([\d.,]+) pasos\/min\)\. Dar pasos más cortos y rápidos \(subir 5-10 %\) reduce el impacto en rodillas y caderas\.$/, 'Low cadence ($1 steps/min). Shorter, quicker steps (5–10% more) reduce the impact on knees and hips.'],
  [/^Buena cadencia \(([\d.,]+) pasos\/min\)\.$/, 'Good cadence ($1 steps/min).'],
  [/^Rebotas mucho \(~([\d.,]+) cm\)\. Piensa en avanzar, no en saltar: más cadencia y menos impulso hacia arriba\.$/, 'You bounce a lot (~$1 cm). Think forward, not up: more cadence and less upward push.'],
  [/^Rebote controlado \(~([\d.,]+) cm\)\.$/, 'Controlled bounce (~$1 cm).'],
  [/^Posible sobrezancada: el pie cae ~([\d.,]+) cm delante de la cadera\. Intenta apoyar más debajo del cuerpo\.$/, 'Possible overstriding: your foot lands ~$1 cm in front of your hips. Try to land more under your body.'],
  [/^Tronco muy inclinado hacia adelante \(([\d.,]+)°\)\. Corre «alto», con una inclinación leve desde los tobillos\.$/, 'Torso leaning too far forward ($1°). Run tall, with a slight lean from the ankles.'],
  [/^Tronco hacia atrás \(([\d.,-]+)°\): inclínate levemente hacia adelante\.$/, 'Torso leaning back ($1°): lean slightly forward.'],
  [/^Pasos desiguales entre piernas \(([\d.,]+) %\)\. Puede ser cansancio, una molestia o la grabación\.$/, 'Uneven steps between legs ($1%). It may be fatigue, discomfort or the recording.'],
  [/^La rodilla queda muy doblada abajo \(([\d.,]+)°\): el sillín parece BAJO\. Súbelo 1-2 cm y vuelve a medir\.$/, 'Your knee stays very bent at the bottom ($1°): the saddle looks LOW. Raise it 1–2 cm and measure again.'],
  [/^La rodilla casi se estira abajo \(([\d.,]+)°\): el sillín parece ALTO\. Bájalo 1 cm y vuelve a medir\.$/, 'Your knee almost straightens at the bottom ($1°): the saddle looks HIGH. Lower it 1 cm and measure again.'],
  [/^Calculado con tu equipo: (.*)$/, 'Calculated with your equipment: $1'],
  [/^(No pude enviar el reporte|No pude guardar el entrenamiento|No pude guardar los cambios|No pude restaurar todo|No se pudo recalcular la serie|No se pudo rehacer el video): (.*)$/,
    (m, x, r) => `${{ 'No pude enviar el reporte': "Couldn't send the report", 'No pude guardar el entrenamiento': "Couldn't save the workout", 'No pude guardar los cambios': "Couldn't save the changes", 'No pude restaurar todo': "Couldn't restore everything", 'No se pudo recalcular la serie': "Couldn't recalculate the set", 'No se pudo rehacer el video': "Couldn't rebuild the video" }[x]}: ${EN[r] || r}`],
  // v2.75.0 avisos de técnica (con número de reps) y notas con números
  [/^Rep parcial: recorrido corto$/, 'Partial rep: short range'], [/^Faltó profundidad \(cadera ~(\d+) cm sobre la rodilla\)$/, 'Not deep enough (hips ~$1 cm above the knee)'],
  [/^Balanceaste el torso \(~(\d+) cm de impulso\)$/, 'You swung your torso (~$1 cm of momentum)'], [/^Brazo (izquierdo|derecho) recorrió ~(\d+) cm menos$/, (m, l, n) => `${l === 'izquierdo' ? 'Left' : 'Right'} arm moved ~${n} cm less`],
  [new RegExp(`^(${Object.keys(TEC).map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')}): (en todas las reps|(reps?) ([\\d, ]+))$`), (m, x, todo, r, n) => `${TEC[x]}: ${todo === 'en todas las reps' ? 'on every rep' : `${r} ${n}`}`],
  [/^Rep ([\d, ]+) excluidas? del cálculo: recorrido y velocidad muy distintos al resto \(probable error de medición, movimiento de cámara o un tirón\)\.$/, (m, n) => `Rep${n.includes(',') ? 's' : ''} ${n} excluded from the calculation: range and velocity very different from the rest (probably a measurement error, camera movement or a jerk).`],
  [/^Se usó tu perfil carga-velocidad personal \(confianza (alta|media)(, tu velocidad mínima: ([\d.,]+) m\/s)?\)\.$/, (m, c, x, v) => `Your personal load-velocity profile was used (${c === 'alta' ? 'high' : 'medium'} confidence${v ? `, your minimum velocity: ${v} m/s` : ''}).`],
];

// v2.74.0 nombres y consejos de los ejercicios; el buscador también encuentra el nombre en inglés
import { EJERCICIOS } from './ejercicios.js';
import { EJ_EN, HINTS_EN } from './ejercicios_en.js';
for (const x of EJERCICIOS) {
  const n = EJ_EN[x.id]; if (!n) continue;
  if (!Object.prototype.hasOwnProperty.call(EN, x.nombre)) EN[x.nombre] = n[0];
  if (x.corto && !Object.prototype.hasOwnProperty.call(EN, x.corto)) EN[x.corto] = n[1];
  x.nombreEn = n[0].toLowerCase(); // para el buscador (no se toca «en», que usa el importador de Hevy)
}
Object.assign(EN, HINTS_EN);
